<?php
require_once __DIR__.'/../config/app.php';require_admin();$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$errors=[];if(is_post()){verify_csrf();$name=trim($_POST['name']??'');$sku=strtoupper(trim($_POST['sku']??''));$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$min=(int)($_POST['minimum_stock']??0);if($name===''||$sku===''||$category<1||$price<0||$stock<0)$errors[]='Data produk tidak valid.';$s=db()->prepare('SELECT id FROM products WHERE sku=?');$s->execute([$sku]);if($s->fetch())$errors[]='SKU sudah digunakan.';if(!$errors){$image=null;try{$image=upload_image($_FILES['image']??[],'uploads/products','product');$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO products(category_id,sku,name,slug,description,price,stock,minimum_stock,image,is_featured,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$category,$sku,$name,unique_slug('products',$name),trim($_POST['description']??''),$price,$stock,$min,$image,isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0]);$productId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,movement_type,quantity,stock_before,stock_after,notes) VALUES(?,?,'initial',?,0,?,'Stok awal produk')")->execute([$productId,current_user()['id'],$stock,$stock]);$pdo->commit();flash('success','Produk berhasil ditambahkan.');redirect('admin/products.php');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();remove_upload($image);$errors[]=$e->getMessage();}}}$pageTitle='Tambah Produk';require APP_ROOT.'/includes/admin-header.php';?>
<?php foreach($errors as $error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endforeach;require __DIR__.'/product-form.php';require APP_ROOT.'/includes/admin-footer.php';?>
